// index.js -- the whole Worker. ./worker.js is generated by build.sh from
// Worker.java's exports: it instantiates the module, runs its static
// initializers, and turns each export into a function over JavaScript values.

import module from "./worker.wasm";
import { instantiate } from "./worker.js";

// Once per isolate, not per request: the instance, and Worker's static state
// with it, lives as long as the isolate does.
const java = instantiate(module);

export default {
  async fetch(request) {
    const { pathname, searchParams } = new URL(request.url);
    const number = (name, fallback) => Number(searchParams.get(name) ?? fallback);

    switch (pathname) {
      case "/":
        // A String each way: the glue copies the argument in and the result out.
        return text(java.greet(searchParams.get("name") ?? "Workers"));

      case "/add": {
        // An int each way: JavaScript just gets a number back.
        const [a, b] = [number("a", 2), number("b", 3)];
        return text(`${a} + ${b} = ${java.add(a, b)}`);
      }

      case "/fib": {
        const n = number("n", 20);
        return text(`fib(${n}) = ${java.fib(n)}`);
      }

      default:
        return text(`no route for ${pathname}\n\ntry /, /?name=you, /add?a=2&b=3, /fib?n=20`, 404);
    }
  },
};

function text(body, status = 200) {
  return new Response(body + "\n", {
    status,
    headers: { "content-type": "text/plain; charset=utf-8" },
  });
}
